targets.query:
from(bucket: "telemetry")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r["subsystem"] == "EPS")
  |> filter(fn: (r) => r["_field"] == "BATTERY_PACK_TEMPERATURE")
  |> map(fn: (r) => ({
      r with
      _value: float(v: r._value) / 100.0
  }))

